namespace {
int checks=0,failures=0;void expect(bool okay,const std::string& text){++checks;if(!okay){++failures;std::cerr<<"FAIL: "<<text<<'\n';}}
template<class F>void rejects(F fn,int code,const char* text){bool okay=false;try{fn();}catch(const penta::units::Error& e){okay=e.status==code;}expect(okay,text);}
penta_units_request_v1 operation(penta::units::Module& module,unsigned kind,const std::vector<double>& a,const char* aUnit,const std::vector<double>& b,const char* bUnit){penta_units_request_v1 r{};r.operation=kind;r.a_unit=module.parse(aUnit);r.b_unit=module.parse(bUnit);r.a=a.data();r.b=b.data();r.a_rows=r.b_rows=1;r.a_columns=a.size();r.b_columns=b.size();r.max_work=1000000000;return r;}
void native(){
    penta::units::Module module;const auto force=module.parse("N"),equivalent=module.parse("kg m s^-2");expect(std::equal(force.dimensions,force.dimensions+7,equivalent.dimensions)&&equivalent.scale==1,"Derived force dimension agrees with independent SI base exponents.");expect(force.dimensions[0]==1&&force.dimensions[1]==1&&force.dimensions[2]==-2,"Fixed exponent order is length,mass,time,current,temperature,amount,luminous intensity.");expect(std::abs(module.parse("mg").scale/1e-6-1)<1e-15,"Mass prefixes apply to gram, not kilogram.");expect(std::abs(module.parse("N/(cm^2)").scale/1e4-1)<1e-15,"Nested area conversion preserves dimension and scale.");expect(std::abs(module.parse("km/h").scale/(1000.0/3600)-1)<1e-15,"Speed conversion scale agrees with the independent hour definition.");
    std::vector<double> a{100,250},b{10,20};auto r=operation(module,PENTA_UNIT_CONVERT,a,"cm",{},"m");const auto converted=module.execute(r);expect(converted.values==std::vector<double>({1,2.5}),"Native array conversion cm→m.");a={1,2};r=operation(module,PENTA_UNIT_ADD,a,"m",b,"cm");const auto sum=module.execute(r);expect(std::abs(sum.values[0]-1.1)<1e-15&&std::abs(sum.values[1]-2.2)<1e-15&&sum.unit.scale==1,"Addition converts the right operand into left display units.");r.operation=PENTA_UNIT_SUBTRACT;const auto difference=module.execute(r);expect(std::abs(difference.values[0]-.9)<1e-15&&std::abs(difference.values[1]-1.8)<1e-15,"Dimension-compatible native subtraction.");
    a={50};b={2};r=operation(module,PENTA_UNIT_MULTIPLY,a,"cm",b,"m");auto product=module.execute(r);expect(product.values[0]==1&&product.unit.dimensions[0]==2&&product.unit.scale==1,"Multiplication emits canonical SI magnitudes and squared length.");a={100};b={2};r=operation(module,PENTA_UNIT_DIVIDE,a,"km",b,"h");expect(std::abs(module.execute(r).values[0]-100000.0/7200)<1e-14,"Quantity division uses both explicit conversion factors.");a={2};r=operation(module,PENTA_UNIT_POWER,a,"cm",{},"1");r.exponent=-1;expect(module.execute(r).values[0]==50,"Negative integer quantity power gives reciprocal SI units.");r.exponent=2;expect(std::abs(module.execute(r).values[0]-.0004)<1e-19,"Integer power applies to numerical values and dimensions.");
    a={90};r=operation(module,PENTA_UNIT_CONVERT,a,"deg",{},"rad");expect(std::abs(module.execute(r).values[0]-std::acos(-1.0)/2)<1e-15,"Degree/radian conversion is explicitly dimensionless linear SI.");a={25};r=operation(module,PENTA_UNIT_CONVERT,a,"%",{},"1");expect(module.execute(r).values[0]==.25,"Percent conversion is explicit rather than silently stripped.");
    a={};b={2};r=operation(module,PENTA_UNIT_MULTIPLY,a,"m",b,"s");expect(module.execute(r).values.empty(),"Empty quantity array times scalar retains empty shape.");a={2};b={};r=operation(module,PENTA_UNIT_MULTIPLY,a,"m",b,"s");expect(module.execute(r).values.empty(),"Scalar times empty quantity array retains empty shape.");
    a={1e308};r=operation(module,PENTA_UNIT_CONVERT,a,"Ym",{},"Ym");expect(module.execute(r).values[0]==1e308,"Conversion avoids premature overflow of a large common scale.");a={1e308};b={1e-308};r=operation(module,PENTA_UNIT_MULTIPLY,a,"Yrad",b,"yrad");expect(std::abs(module.execute(r).values[0]-1)<1e-15,"Scaled multiplication preserves a finite physical result.");a={1e-288};r=operation(module,PENTA_UNIT_POWER,a,"Yrad^12",{},"1");r.exponent=32;expect(std::abs(module.execute(r).values[0]-1)<1e-13,"Canonical power avoids overflow of an unused display-unit scale.");
    a.assign(100000,1);r=operation(module,PENTA_UNIT_CONVERT,a,"m",{},"cm");penta::runtime::ParallelSettings parallel;parallel.threads=4;parallel.serialThreshold=1;const auto many=module.execute(r,parallel);expect(std::all_of(many.values.begin(),many.values.end(),[](double x){return x==100;})&&many.parallel.parallelCalls>0&&many.parallel.threadsUsed<=4,"Native SI array conversion shares Studio's CPU budget.");auto stopped=std::make_shared<std::atomic_bool>(true);rejects([&]{module.execute(r,parallel,stopped);},3,"SI array cancellation releases the shared reservation.");auto limited=r;limited.max_work=1;rejects([&]{module.execute(limited);},7,"SI array work allowance is enforced.");
    for(const auto* invalid:{"degC","degF","Celsius","(m/s","m//s","m^1.5","m^33","m+s","unknown",""})rejects([&]{module.parse(invalid);},1,"Invalid/affine SI expression is rejected.");
    a={1};b={1};r=operation(module,PENTA_UNIT_ADD,a,"m",b,"s");rejects([&]{module.execute(r);},1,"Incompatible physical dimensions cannot be added.");r=operation(module,PENTA_UNIT_CONVERT,a,"m",{},"s");rejects([&]{module.execute(r);},1,"Incompatible physical dimensions cannot be converted.");a={1};b={0};r=operation(module,PENTA_UNIT_DIVIDE,a,"m",b,"s");rejects([&]{module.execute(r);},2,"Quantity division by zero is diagnosed.");a={std::numeric_limits<double>::quiet_NaN()};r=operation(module,PENTA_UNIT_POWER,a,"1",{},"1");r.exponent=0;rejects([&]{module.execute(r);},2,"NaN cannot bypass quantity validation through exponent zero.");a={1e-300};r=operation(module,PENTA_UNIT_POWER,a,"1",{},"1");r.exponent=32;rejects([&]{module.execute(r);},2,"Powered nonzero underflow is diagnosed.");
    a={1,2};b={3,4};r=operation(module,PENTA_UNIT_MULTIPLY,a,"m",b,"s");r.a_rows=2;r.a_columns=1;r.b_rows=1;r.b_columns=2;rejects([&]{module.execute(r);},1,"Quantities never invent an implicit outer product or non-scalar broadcast.");
    a={100};r=operation(module,PENTA_UNIT_CONVERT,a,"cm",{},"m");auto first=std::async(std::launch::async,[&]{return module.execute(r);});auto second=std::async(std::launch::async,[&]{return module.execute(r);});expect(first.get().values==second.get().values,"Independent native SI callers are thread-safe after failures.");
    const auto fractional=module.parseExtended("kg m^(1/2) s^(-3/2)");expect(fractional.numerator[0]==1&&fractional.denominator[0]==2&&fractional.numerator[2]==-3&&fractional.denominator[2]==2,"Rational unit exponents retain exact reduced integer numerator/denominator pairs.");
    auto extended=[&](unsigned op,const std::vector<double>&left,const char*leftUnit,const std::vector<double>&right,const char*rightUnit){penta_units_request_v2 q{};q.operation=op;q.a=left.data();q.b=right.data();q.a_rows=q.b_rows=1;q.a_columns=left.size();q.b_columns=right.size();q.a_unit=module.parseExtended(leftUnit);q.b_unit=module.parseExtended(rightUnit);q.max_work=100000000;return q;};
    a={4};auto q=extended(PENTA_UNIT_POWER,a,"cm^2",{},"1");q.power_numerator=1;q.power_denominator=2;auto squareRoot=module.execute(q);expect(std::abs(squareRoot.values[0]-.02)<1e-16&&squareRoot.unit.numerator[0]==1&&squareRoot.unit.denominator[0]==1,"Fractional physical power uses SI magnitude and reduces squared-length dimensions.");
    a={-8};q=extended(PENTA_UNIT_POWER,a,"m^3",{},"1");q.power_numerator=1;q.power_denominator=3;expect(std::abs(module.execute(q).values[0]+2)<1e-15,"Odd-denominator real roots preserve the real branch of negative values.");q.power_numerator=2;expect(std::abs(module.execute(q).values[0]-4)<1e-14,"Even numerator over odd denominator retains the positive real power.");q.power_numerator=1;q.power_denominator=2;rejects([&]{module.execute(q);},2,"Even-denominator roots of negative real magnitudes reject undefined real branches.");
    a={0,100};q=extended(PENTA_UNIT_CONVERT,a,"degC",{},"degF");const auto fahrenheit=module.execute(q);expect(std::abs(fahrenheit.values[0]-32)<1e-12&&std::abs(fahrenheit.values[1]-212)<1e-12,"Absolute Celsius to Fahrenheit agrees with fixed physical references.");
    a={20};b={18};q=extended(PENTA_UNIT_ADD,a,"degC",b,"delta_degF");expect(std::abs(module.execute(q).values[0]-30)<1e-12,"An absolute temperature plus a Fahrenheit delta preserves absolute Celsius display units.");
    a={68};b={10};q=extended(PENTA_UNIT_SUBTRACT,a,"degF",b,"degC");const auto temperatureDifference=module.execute(q);expect(std::abs(temperatureDifference.values[0]-18)<1e-12&&temperatureDifference.unit.kind==PENTA_UNIT_LINEAR,"Subtracting absolute temperatures yields a linear delta in left display units.");
    q.operation=PENTA_UNIT_ADD;rejects([&]{module.execute(q);},1,"Two absolute temperatures cannot be added.");a={-274};q=extended(PENTA_UNIT_CONVERT,a,"degC",{},"K_abs");rejects([&]{module.execute(q);},2,"Absolute temperatures below zero Kelvin are rejected.");
    a={0,30};q=extended(PENTA_UNIT_CONVERT,a,"dBm",{},"W");const auto watts=module.execute(q);expect(std::abs(watts.values[0]-.001)<1e-17&&std::abs(watts.values[1]-1)<1e-14,"dBm levels convert through the explicit one milliwatt power reference.");
    a={1};q=extended(PENTA_UNIT_CONVERT,a,"W",{},"dBm");expect(std::abs(module.execute(q).values[0]-30)<1e-13,"A one watt linear quantity converts to thirty dBm.");a={2};q=extended(PENTA_UNIT_CONVERT,a,"V",{},"dBV");expect(std::abs(module.execute(q).values[0]-20*std::log10(2))<1e-13,"dBV uses the explicit twenty-log amplitude convention.");a={0};q=extended(PENTA_UNIT_CONVERT,a,"V",{},"dBV");rejects([&]{module.execute(q);},2,"Logarithmic target levels require positive linear values.");
    for(const auto* bad:{"m^(1/0)","m^(1/33)","degC*m","dBm^2","m^(1.5/2)","m^(1025/1)"})rejects([&]{module.parseExtended(bad);},1,"Invalid rational, affine-product and logarithmic-power expressions reject.");
    a.assign(100000,4);q=extended(PENTA_UNIT_POWER,a,"m",{},"1");q.power_numerator=1;q.power_denominator=2;auto parallelRoot=module.execute(q,parallel);expect(parallelRoot.parallel.parallelCalls>0&&parallelRoot.parallel.threadsUsed<=4&&parallelRoot.values.back()==2,"Rational native quantity arrays share the same CPU budget as legacy units.");
}
#ifndef PENTA_UNITS_NATIVE_ONLY
void language(){
    auto run=[&](const std::string& source,bool good=true){const auto result=penta::runtime::execute(source);expect(result.ok()==good,source);if(good&&!result.ok()){for(const auto& d:result.analysis.diagnostics)std::cerr<<d.code<<": "<<d.message<<'\n';for(const auto& d:result.runtimeDiagnostics)std::cerr<<d.code<<": "<<d.message<<'\n';}return result;};
    run("record length_q=quantity([100,250],\"cm\");record converted=unitconvert(length_q,\"m\");matrix values=unitvalues(converted);assert(values==[1,2.5]);assert(unitcompatible(converted,\"km\")==1);assert(unitcompatible(\"m\",\"s\")==0);assert(unitinfo(\"N\").dimensions==[1,1,-2,0,0,0,0]);");
    run("record a=quantity([1,2],\"m\");record b=quantity([10,20],\"cm\");matrix added=unitvalues(unitadd(a,b));assert(norm(added-[1.1,2.2])<1e-14);record area_q=unitmul(a,b);assert(unitcompatible(area_q,\"m^2\"));record speed_q=unitdiv(quantity(100,\"km\"),quantity(2,\"h\"));matrix velocity=unitvalues(unitconvert(speed_q,\"km/h\"));assert(abs(velocity(1)-50)<1e-13);record reciprocal=unitpow(quantity(2,\"cm\"),-1);matrix inverse_length=unitvalues(reciprocal);assert(inverse_length(1)==50);");
    run("record a=quantity(1,\"m\");record b=quantity(1,\"s\");record wrong=unitadd(a,b);",false);run("record a=quantity(1,\"m\");record wrong=unitconvert(a,\"s\");",false);run("record a=quantity(1,\"m\");record b=quantity(2,\"m\");record wrong=a+b;",false);run("record a=quantity(1,\"m\");real wrong=sin(a);",false);
    run("record a=quantity(20,\"degC\");record b=unitadd(a,quantity(18,\"delta_degF\"));matrix c=unitvalues(b);assert(abs(c(1)-30)<1e-12);matrix absolute_k=unitvalues(unitconvert(b,\"K_abs\"));assert(abs(absolute_k(1)-303.15)<1e-12);record difference=unitsub(quantity(68,\"degF\"),quantity(10,\"degC\"));assert(abs(unitvalues(difference)(1)-18)<1e-12);");
    run("record unit_root=unitpow(quantity(4,\"cm^2\"),1,2);assert(unitcompatible(unit_root,\"m\"));assert(abs(unitvalues(unit_root)(1)-.02)<1e-14);record fractional=quantity(2,\"m^(1/2)\");assert(fractional.numerators==[1,0,0,0,0,0,0]);assert(fractional.denominators==[2,1,1,1,1,1,1]);assert(unitinfo(\"m^(1/2)\").dimensions==[.5,0,0,0,0,0,0]);");
    run("matrix power=unitvalues(unitconvert(quantity([0,30],\"dBm\"),\"W\"));assert(norm(power-[.001,1])<1e-13);matrix voltage=unitvalues(unitconvert(quantity(2,\"V\"),\"dBV\"));assert(abs(voltage(1)-20*log10(2))<1e-12);");
    run("record imaginary=quantity(1+2*i-3*j+.4*ell,\"cm\");pentarnion p=unitvalues(unitconvert(imaginary,\"m\"));assert(sqrt(norm2(p-.01*(1+2*i-3*j+.4*ell)))<1e-13);record product=unitmul(imaginary,quantity(i,\"s\"));pentarnion q=unitvalues(product);assert(sqrt(norm2(q-.01*((1+2*i-3*j+.4*ell)*i)))<1e-13);assert(unitcompatible(product,\"m*s\"));");
    run("algebra H=builtin_algebra(\"quaternion\");element<H> p=H.one+2*H.i;record a=quantity(p,\"cm\");record b=quantity(H.j,\"s\");element<H> result=unitvalues(unitmul(a,b));assert(algebra_norm(result-.01*(p*H.j))<1e-13);element<H> recovered=unitvalues(unitdiv(unitmul(a,b),b));assert(algebra_norm(recovered-.01*p)<1e-13);record squared=unitpow(a,2);element<H> square=unitvalues(squared);assert(algebra_norm(square-.0001*(p*p))<1e-13);");
    run("record q=unitadd(quantity(10,\"degC\"),quantity(20,\"degC\"));",false);run("record q=quantity(-274,\"degC\");",false);run("record q=quantity(i,\"degC\");",false);run("record q=unitpow(quantity(i,\"m\"),1,2);",false);run("record q=unitadd(quantity(0,\"dBm\"),quantity(3,\"dBm\"));",false);
    penta::language::AnalysisOptions old;old.languageVersion="0.1";expect(!penta::language::analyse("record a=quantity(1,\"m\");",old).ok(),"SI quantity extension preserves language0.1.");
}
#endif
}
int main(){try{native();
#ifndef PENTA_UNITS_NATIVE_ONLY
language();
#endif
}catch(const std::exception& e){++failures;std::cerr<<e.what()<<'\n';}std::cout<<checks<<" SI quantity checks, "<<failures<<" failures\n";return failures?1:0;}
